function readWorkspace(character:number,space:'known'|'wormhole'){
 let saved:unknown=null;
 try{if(typeof window!=='undefined')saved=JSON.parse(sessionStorage.getItem('kairo-universe-workspace:'+character+':'+space)||'null');}catch{ /* Invalid saved state restores the supported defaults. */ }
 return restoreUniverseWorkspace(saved,space);
}

